from django.db import migrations, models


def move_imei_out_of_notes(apps, schema_editor):
    """
    Earlier versions of the gadget inventory kept IMEI numbers in the notes as a first line
    "IMEI: a / b / c". Move them into the new IMEI columns (only where those are still empty) and
    take that line out of the notes. Anything that doesn't fit in three columns stays in the notes.
    """
    Asset = apps.get_model('helpdesk', 'Asset')
    db = schema_editor.connection.alias
    for a in Asset.objects.using(db).filter(notes__startswith='IMEI: ', imei='', imei2='', imei3=''):
        first, _, rest = a.notes.partition('\n')
        found = [x.strip() for x in first[len('IMEI: '):].split(' / ') if x.strip()]
        if not found or any(len(x) > 40 for x in found):
            continue
        slots = found[:3] + [''] * (3 - len(found[:3]))
        leftover = found[3:]
        a.imei, a.imei2, a.imei3 = slots
        a.notes = '\n'.join(([('More IMEIs: ' + ' / '.join(leftover))] if leftover else []) + ([rest] if rest else []))
        a.save(update_fields=['imei', 'imei2', 'imei3', 'notes'])


